// Import one source module under the checkout's tsx loader; never invoke workload code.
import assert from 'node:assert/strict'
import { Session } from 'node:inspector'
import { createHash } from 'node:crypto'
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { pathToFileURL } from 'node:url'

const [checkoutArg, targetArg, outputArg] = process.argv.slice(2)
assert.ok(checkoutArg && targetArg && outputArg, 'Usage: node --import tsx capture-generated.mjs <checkout> <source-relative-path> <output-directory>')
const checkout = resolve(checkoutArg)
const target = resolve(checkout, targetArg)
const output = resolve(outputArg)
const targetUrl = pathToFileURL(target).href
const sha256 = value => createHash('sha256').update(value).digest('hex')
const session = new Session()
const captures = []
const pending = []
session.connect()
const post = (method, params = {}) => new Promise((ok, reject) => session.post(method, params, (error, result) => error ? reject(error) : ok(result)))
session.on('Debugger.scriptParsed', ({ params }) => {
  if (params.url !== targetUrl) return
  pending.push(post('Debugger.getScriptSource', { scriptId: params.scriptId }).then(result => captures.push({ params, source: result.scriptSource })))
})
try {
  await post('Debugger.enable')
  await import(targetUrl)
  await Promise.all(pending)
} finally {
  session.disconnect()
}
assert.equal(captures.length, 1, 'Expected exactly one generated script for the target URL')
const { params, source } = captures[0]
const match = source.match(/sourceMappingURL=data:application\/json(?:;charset=[^;,]+)?;base64,([^\s]+)/)
assert.ok(match, 'tsx generated source has no inline JSON source map')
const map = JSON.parse(Buffer.from(match[1], 'base64').toString('utf8'))
mkdirSync(output, { recursive: true })
writeFileSync(resolve(output, 'replay-codec.generated.js'), source)
writeFileSync(resolve(output, 'replay-codec.map.json'), JSON.stringify(map, null, 2) + '\n')
const metadata = { target, targetUrl, node: process.version, argv: process.argv, execArgv: process.execArgv,
  originalSha256: sha256(readFileSync(target)), generatedSha256: sha256(source), generatedBytes: Buffer.byteLength(source),
  parsed: params, mapSources: map.sources, sourcesContentSha256: map.sourcesContent?.map(value => value === null ? null : sha256(value)) }
writeFileSync(resolve(output, 'generated-metadata.json'), JSON.stringify(metadata, null, 2) + '\n')
console.log(JSON.stringify({ output, originalSha256: metadata.originalSha256, generatedSha256: metadata.generatedSha256 }))

