import assert from 'node:assert/strict'
import { execFileSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import { readFileSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { performance, PerformanceObserver } from 'node:perf_hooks'
import { pathToFileURL } from 'node:url'
import { setImmediate as immediate } from 'node:timers/promises'

const usage = `Diagnostic only; does not modify the selected checkout or its harness.
node --import tsx diagnose.mjs --checkout <tree> --fixture <fixture.json> --output <report.json>
  [--names matched|override] [--warmups 1] [--repeats 3] [--json] [--allow-unconstrained]
For a separate sampled run, prepend node --cpu-prof --cpu-prof-interval=500
--cpu-prof-dir=<output-dir> --cpu-prof-name=tail.cpuprofile. Named tailCommand26 and
tailCommand233 ancestors cover all three command phases (fixture indices, zero based).
No artificial GC, date/UUID overrides, networking, or acceptance calculations.
