const value = (flag, fallback) => {
  const index = args.indexOf(flag)
  if (index < 0) return fallback
  assert.ok(args[index + 1] && !args[index + 1].startsWith('--'), `Missing value for ${flag}`)
  return args[index + 1]
}
const checkout = resolve(value('--checkout', process.cwd()))
assert.ok(value('--fixture') && value('--output'), usage)
const fixturePath = resolve(value('--fixture'))
const outputPath = resolve(value('--output'))
assert.ok(!outputPath.startsWith(checkout + '/') && outputPath !== fixturePath, 'Keep diagnostics outside the checkout and fixture')
const nameMode = value('--names', 'matched')
const warmups = Number(value('--warmups', '1'))
const repeats = Number(value('--repeats', '3'))
assert.ok(['matched', 'override'].includes(nameMode))
assert.ok(Number.isSafeInteger(warmups) && warmups >= 0)
assert.ok(Number.isSafeInteger(repeats) && repeats > 0)
const jsonStages = args.includes('--json')
const load = path => import(pathToFileURL(resolve(checkout, path)).href)
const [{ runRoomWorkload }, { GameSession }, { RoomCommitter }, { Broadcaster },
  { SqliteRoomPersistence }, { RoomHistoryStore }, { readCgroupLimits, assertResourceLimits }] = await Promise.all([
  load('scripts/bench/room-performance.ts'), load('server/game/authoritative-session.ts'),
  load('server/game/room-committer.ts'), load('server/connection/broadcaster.ts'),
  load('server/game/persistence/sqlite-adapter.ts'), load('server/game/persistence/room-history-store.ts'),
  load('scripts/bench/room-capacity.ts'),
