const sourceFiles = ['scripts/bench/room-performance.ts', 'server/game/authoritative-session.ts',
  'server/game/room-committer.ts', 'server/connection/broadcaster.ts', 'server/game/persistence/sqlite-adapter.ts',
  'server/game/persistence/room-history-store.ts', 'shared/session/sync-payload.ts', 'shared/session/session-core.ts']
