let activeCommand = null
let armed = false
let ruleDepth = 0
let spanId = 0
const stack = []
const hrtimeUs = () => Number(process.hrtime.bigint() / 1000n)
function tailCommand26(run) { return run() }
function tailCommand233(run) { return run() }

function measure(phase, original, self, arguments_, details = {}) {
  if (!activeRun || !activeCommand) return Reflect.apply(original, self, arguments_)
  const command = activeCommand
  const span = { id: ++spanId, parentId: stack.at(-1)?.id ?? null, phase, ...details }
  const cpuBefore = process.cpuUsage()
  span.startMs = performance.now()
  stack.push(span)
  try {
    if (span.parentId === null && command.commandIndex === 26) return tailCommand26(() => Reflect.apply(original, self, arguments_))
    if (span.parentId === null && command.commandIndex === 233) return tailCommand233(() => Reflect.apply(original, self, arguments_))
