        return measure('sqlite.transaction', transaction, this, transactionArguments)
      })
      instrumentedPersistence.add(this)
    }
    return measure('sqlite.commitReplay', original, this, arguments_, {
      stepNo: arguments_[0].step.stepNo, payloadKind: arguments_[0].step.payloadKind,
      checkpointStepNo: arguments_[0].step.checkpointStepNo, hasResult: arguments_[0].result !== undefined,
      payloadBytes: arguments_[0].step.payloadGzip.length,
    })
  })
