    wrap(RoomHistoryStore.prototype, method, original => function (...arguments_) {
      return measure(`history.${method}`, original, this, arguments_)
    })
  }
  wrap(GameSession.prototype, 'buildSyncPayload', original => function (...arguments_) {
    return measure('buildSyncPayload', original, this, arguments_, { viewerPlayerId: arguments_[1] })
  })
