        assert.ok(activeCommand, 'Packet emitted outside an attributed command')
        assert.equal(packet.commandIndex, activeCommand.commandIndex)
        activeCommand.lastSinkMs = performance.now()
        activeCommand.sinkCalls += 1
        activeCommand.viewers.push(packet.playerIndex)
