      assert.equal(activeCommand, null, 'Last command did not complete')
      assert.equal(current.commands.length, commands.length)
      assert.equal(current.report.commandSamples.length, commands.length)
      for (const [index, command] of current.commands.entries()) {
        const sample = current.report.commandSamples[index]
        assert.equal(command.commandIndex, sample.commandIndex)
        assert.equal(command.classification, sample.classification)
        assert.equal(command.sinkCalls, sample.sentPackets)
        assert.equal(command.sinkCalls, command.classification === 'committed' ? workload.players : 0)
        for (const phase of ['rules', 'commit', 'broadcast']) {
          assert.equal(command.phases.filter(span => span.phase === phase).length,
            phase === 'broadcast' && command.classification !== 'committed' ? 0 : 1)
        }
        command.sample = sample
      }
      assert.deepEqual(current.commands.filter(command => command.classification === 'committed').map(command => command.frameHash), current.report.hashes)
      assert.deepEqual(current.commands.map(command => command.classification), current.report.classifications)
    } finally {
      current.endMs = performance.now()
      current.endHrtimeUs = hrtimeUs()
      activeRun = null
      activeCommand = null
      armed = false
      // GC observer delivery is asynchronous; drain between synchronous runs.
      await immediate()
      await immediate()
      ingestGc(observer.takeRecords())
    }
  }
} catch (error) {
  failure = { message: String(error), stack: error?.stack }
} finally {
  while (restores.length) restores.pop()()
  await immediate()
  ingestGc(observer.takeRecords())
  observer.disconnect()
