const report = {
  schemaVersion: 1, diagnosticOnly: true, node: process.version, limits, checkout,
  commit: execFileSync('git', ['rev-parse', 'HEAD'], { cwd: checkout, encoding: 'utf8' }).trim(),
  fixture: fixturePath, fixtureSha256: sha256(fixtureText), sourceSha256,
  diagnosticSourceSha256: sha256(readFileSync(new URL(import.meta.url))),
  warmups, repeats, nameMode, jsonStages, fixtureCommands: workload.commands.length,
  nonRestartCommands: commands.length, argv: process.argv, execArgv: process.execArgv,
  clocks: { performanceTimeOriginMs: performance.timeOrigin, intervalClock: 'performance.now milliseconds; GC entries use the same origin',
    cpuProfileAlignment: 'Command/run startHrtimeUs and endHrtimeUs are process.hrtime microseconds. Prefer named tailCommand26/tailCommand233 profile ancestors; warmup and iteration remain explicit in this report.' },
  measurement: [
    'Inclusive synchronous spans. Nested phases and nested JSON.stringify calls MUST NOT be summed with parents.',
    'rules, commit and broadcast are disjoint top-level wrappers. CPU is process-wide user/system CPU, including concurrent runtime workers; it is not thread-exclusive CPU.',
    'sqlite.transaction includes transaction callback and SQLite COMMIT/WAL auto-checkpoint. Its duration alone does not prove a checkpoint occurred.',
    'buildSyncPayload excludes final Room-name projection and packet JSON encoding. broadcast includes those stages and synchronous socket sinks.',
    'Harness commandSamples retain command entry through last synchronous sink send; no routing, queueing, network, or browser rendering. Wrapper/callback allocations, clocks, process.cpuUsage and optional profiler perturb timings/GC.',
    'GC entries are observed intervals, intersected after all runs. Overlap is correlation, not proof that all overlap was stop-the-world or causal.',
    'Every non-restart fixture command is mapped by the outermost rules entry; getState, initial setup and restart restore are excluded from command spans. Full run reports include existing harness restart costs.',
    'All warmup and measured reports retain hashes/classifications. No acceptance comparison or threshold is computed. JSON.stringify instrumentation is optional and has extra overhead.',
  ],
  gc, runs, failure,
}
writeFileSync(outputPath, JSON.stringify(report, null, 2) + '\n')
console.log(`Saved diagnostic: ${outputPath}`)
if (failure) { console.error(failure.stack ?? failure.message); process.exitCode = 1 }

